        "【重组义务的计量范围】\n通常可以计入重组义务的支出包括：",
        "【重组义务的计量范围】\n| 支出 | 是否通常计入重组义务 |\n| --- | --- |\n| 辞退补偿 | 是，但通过应付职工薪酬核算 |\n| 关闭场所发生的违约赔偿 | 是 |\n| 终止租赁或终止合同的赔偿 | 是 |\n| 与关闭业务直接相关且不可避免的支出 | 是 |",
        "【重组义务的计量范围】\n通常不能计入重组义务的支出包括：",
        "【重组义务的计量范围】\n| 支出 | 理由 |\n| --- | --- |\n| 未来经营损失 | 不是资产负债表日已经承担的现时义务 |\n| 员工再培训支出 | 与未来经营活动相关 |\n| 市场推广支出 | 与未来经营活动相关 |\n| 新系统、新设备投资 | 属于未来经营或资产购建支出 |\n| 留用职工工资 | 通常是未来服务的对价 |",
        "【不能考虑处置相关资产的利得或损失】\n企业在计量与重组义务相关的预计负债时，不应当考虑预期处置相关资产形成的利得或损失。",
        "【不能考虑处置相关资产的利得或损失】\n也就是说，即使资产出售是重组计划的一部分，也不能用预计资产处置收益抵减重组预计负债。",
        "【不能考虑处置相关资产的利得或损失】\n原因在于：",
