        "【不能考虑处置相关资产的利得或损失】\n正确处理是：",
        "【不能考虑处置相关资产的利得或损失】\n```text\n重组预计负债 = 2（亿元）\n```",
        "【不能考虑处置相关资产的利得或损失】\n土地未来出售形成的处置收益，应当在资产处置满足确认条件时单独确认。",
        "【例题：重组直接支出的范围】\n因 A 产品不再符合市场偏好，甲公司决定对 A 产品予以停产。",
        "【例题：重组直接支出的范围】\n相关事项如下：",
