        "【逐项分析】\n因此，与重组有关的直接支出为：",
        "【逐项分析】\n```text\n80 + 300 = 380（万元）\n```",
        "【口径辨析】\n这道题容易混淆“重组义务金额口径”和“具体会计科目口径”。",
