      "id": "long-term-equity-investment-step-acquisition-non-common-control",
      "updatedAt": "2026-06-23",
      "topic": "长期股权投资",
      "difficulty": "系统补齐",
      "question": "多次交易形成非同一控制下企业合并怎么理解？",
      "summary": "多次交易形成非同一控制下企业合并时，最重要的特殊点是：",
      "conclusion": [
        "多次交易形成非同一控制下企业合并时，最重要的特殊点是：",
        "个别报表看账面价值；",
        "合并报表看购买日公允价值。",
        "也就是说，原来持有的股权投资，在个别报表和合并报表中的处理口径不同。"
      ],
      "reasoning": [
        "### 核心结论\n\n多次交易形成非同一控制下企业合并时，最重要的特殊点是：\n\n```text\n个别报表看账面价值；\n合并报表看购买日公允价值。\n```\n\n也就是说，原来持有的股权投资，在个别报表和合并报表中的处理口径不同。\n\n个别报表中，原投资通常不在购买日重新计量为公允价值。\n\n合并报表中，原投资要在购买日按照公允价值重新计量，公允价值与账面价值之间的差额通常计入投资收益。\n\n### 判断逻辑\n\n非同一控制下企业合并本质上适用购买法。\n\n但是，多次交易形成控制时，需要区分两个层面：\n\n1. 个别报表层面，是母公司自己账上的长期股权投资如何确认；\n2. 合并报表层面，是整个企业集团取得被购买方控制权时如何确认合并成本和商誉。\n\n因此，同一笔分步取得控制的交易，在两个层面的处理重点不同。\n\n### 个别报表处理\n\n如果原投资为权益法核算的长期股权投资，后来通过追加投资达到控制，购买日个别报表中：\n\n```text\n长期股权投资初始投资成本\n= 原投资账面价值 + 新增投资成本\n```\n\n这里使用的是原投资账面价值，不是原投资在购买日的公允价值。\n\n新增投资成本通常按照新增支付对价的公允价值确定。\n\n### 原权益法形成项目的处理\n\n购买日之前，原权益法核算形成的其他综合收益、资本公积--其他资本公积，在购买日个别报表中通常暂不处理。\n\n待以后处置该项长期股权投资时，再按照相关资产或负债被投资方直接处置时相同的基础进行会计处理。\n\n简单理解：\n\n```text\n购买日个别报表：\n原投资按账面价值带过来；\n原权益法形成的其他综合收益、其他资本公积先不动。\n```\n\n### 合并报表处理\n\n合并报表层面，非同一控制下企业合并采用购买法。\n\n购买日应当将原来持有的股权按照购买日公允价值重新计量。\n\n合并成本为：\n\n```text\n合并成本\n= 原持有股权在购买日的公允价值\n+ 新增投资支付对价的公允价值\n```\n\n原持有股权的购买日公允价值与其账面价值之间的差额，通常计入投资收益。\n\n```text\n投资收益\n= 原持有股权购买日公允价值 - 原持有股权账面价值\n```\n\n如果公允价值低于账面价值，则确认投资损失。\n\n### 商誉的计算\n\n合并报表中，确定合并成本后，再与取得的被购买方可辨认净资产公允价值份额比较。\n\n```text\n商誉\n= 合并成本 - 被购买方可辨认净资产公允价值份额\n```\n\n如果合并成本小于取得的被购买方可辨认净资产公允价值份额，差额通常计入营业外收入。\n\n### 个别报表和合并报表对比\n\n| 项目 | 个别报表 | 合并报表 |\n| --- | --- | --- |\n| 原投资计量基础 | 原投资账面价值 | 购买日公允价值 |\n| 是否重新计量原投资 | 不重新计量 | 重新计量 |\n| 原投资公允价值与账面价值差额 | 不确认损益 | 通常计入投资收益 |\n| 合并成本口径 | 原投资账面价值 + 新增投资成本 | 原投资购买日公允价值 + 新增对价公允价值 |\n| 是否按购买法确认商誉 | 个别报表不确认商誉 | 合并报表确认商誉或营业外收入 |\n\n### 例子\n\n甲公司原持有乙公司 30% 股权，能够对乙公司施加重大影响，采用权益法核算。\n\n购买日，甲公司追加取得乙公司 40% 股权，取得控制权，形成非同一控制下企业合并。",
        "购买日资料如下：\n\n| 项目 | 金额 |\n| --- | ---: |\n| 原 30% 股权账面价值 | 3,200 |\n| 原 30% 股权购买日公允价值 | 3,800 |\n| 新增 40% 股权支付对价公允价值 | 5,000 |\n| 乙公司可辨认净资产购买日公允价值 | 12,000 |\n\n个别报表中，长期股权投资初始投资成本为：\n\n```text\n3,200 + 5,000 = 8,200\n```\n\n合并报表中，合并成本为：\n\n```text\n3,800 + 5,000 = 8,800\n```\n\n原股权重新计量确认的投资收益为：\n\n```text\n3,800 - 3,200 = 600\n```\n\n取得乙公司可辨认净资产公允价值份额为：\n\n```text\n12,000 * 70% = 8,400\n```\n\n合并报表确认商誉：\n\n```text\n8,800 - 8,400 = 400\n```\n\n### 易错点\n\n1. 不要把个别报表中的原投资账面价值误写成购买日公允价值；\n2. 不要把合并报表中的原投资继续按账面价值计算合并成本；\n3. 个别报表购买日通常不确认原投资公允价值变动产生的投资收益；\n4. 合并报表购买日要重新计量原持有股权，差额通常计入投资收益；\n5. 个别报表不确认商誉，商誉只在合并报表层面确认。\n\n### 记忆口诀\n\n```text\n非同控分步合并：\n个别看账面，合并看公允。\n\n个别不重估，合并要重估。\n账面加新增，是个别成本；\n公允加新增，是合并成本。\n```"
      ],
