        "### 核心结论\n\n其他综合收益的后续去向，先分两大类：\n\n```text\n以后能重分类进损益；\n以后不能重分类进损益。\n```\n\n能重分类进损益的，满足条件或处置时转入投资收益、其他业务成本等损益科目。\n\n不能重分类进损益的，后续不进损益，通常转入留存收益或留在其他综合收益。\n\n### 主要去向总表\n\n| 其他综合收益来源 | 后续去向 | 是否进损益 | 常见去向科目 |\n| --- | --- | --- | --- |\n| 其他债权投资公允价值变动 | 处置时转出 | 进损益 | 投资收益 |\n| 权益法下被投资单位可重分类进损益的其他综合收益 | 处置长期股权投资时，按相同基础转出 | 进损益 | 投资收益 |\n| 外币财务报表折算差额 | 处置境外经营时转出 | 进损益 | 投资收益等 |\n| 现金流量套期储备 | 被套期项目影响损益时转出；如果形成非金融资产或负债，调整其初始成本 | 可能进损益 | 主营业务收入、主营业务成本、财务费用等，或调整资产成本 |\n| 自用房地产或存货转换为公允价值模式计量的投资性房地产，公允价值大于账面价值的差额 | 处置投资性房地产时转出 | 进损益 | 通常转入其他业务成本 |\n| 指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资 | 终止确认时转出 | 不进损益 | 留存收益 |\n| 设定受益计划重新计量变动 | 后续不重分类进损益 | 不进损益 | 留存收益或留在其他综合收益 |\n| 企业自身信用风险变动导致的指定为以公允价值计量且其变动计入当期损益的金融负债公允价值变动 | 终止确认时通常不转损益 | 不进损益 | 留存收益 |\n| 权益法下被投资单位不能重分类进损益的其他综合收益 | 处置长期股权投资时，按相同基础处理 | 不进损益 | 留存收益 |\n\n### 常考项目速记\n\n| 场景 | 去向 |\n| --- | --- |\n| 其他债权投资形成的其他综合收益 | 处置时转投资收益 |\n| 其他权益工具投资形成的其他综合收益 | 处置时转留存收益 |\n| 权益法下可转损益的其他综合收益 | 处置长期股权投资时转投资收益 |\n| 权益法下不可转损益的其他综合收益 | 处置长期股权投资时转留存收益 |\n| 权益法下资本公积--其他资本公积 | 处置长期股权投资时转投资收益 |\n| 投资性房地产转换形成的其他综合收益 | 处置投资性房地产时转其他业务成本 |\n\n### 易错点\n\n1. 其他权益工具投资的其他综合收益，终止确认时不转投资收益，而是转留存收益；\n2. 其他债权投资的其他综合收益，处置时可以转投资收益；\n3. 权益法下的其他综合收益要穿透看被投资单位项目本身；\n4. 投资性房地产转换形成的其他综合收益，处置时通常转入其他业务成本，不是投资收益；\n5. 现金流量套期储备可能直接进损益，也可能调整非金融资产或负债的初始成本。\n\n### 记忆口诀\n\n```text\n其他综合收益先问来源：\n能转损益的，处置进损益；\n不能转损益的，处置进留存。\n\n其他债权进投资收益；\n其他权益进留存收益；\n转换投房进其他业务成本；\n权益法项目按相同基础走。\n```"
