      "difficulty": "系统补齐",
      "question": "权益法下被投资单位发行可累计优先股和非累计优先股怎么理解？",
      "summary": "权益法下，被投资单位发行优先股时，投资单位确认应享有被投资单位净损益份额，要先判断优先股股利是否应当扣除。",
      "conclusion": [
        "权益法下，被投资单位发行优先股时，投资单位确认应享有被投资单位净损益份额，要先判断优先股股利是否应当扣除。",
        "核心区别：",
        "可累计优先股：不宣告也扣。",
        "非累计优先股：宣告才扣。"
      ],
      "reasoning": [
        "### 核心结论\n\n权益法下，被投资单位发行优先股时，投资单位确认应享有被投资单位净损益份额，要先判断优先股股利是否应当扣除。\n\n核心区别：\n\n```text\n可累计优先股：不宣告也扣。\n非累计优先股：宣告才扣。\n```\n\n前提是：被投资单位发行的优先股被分类为权益工具，并且该优先股由其他股东持有。\n\n### 判断逻辑\n\n投资单位采用权益法确认投资收益时，本质上确认的是自己作为普通股股东应享有的被投资单位净利润份额。\n\n如果被投资单位存在优先股股东，应先把归属于优先股股东的利润扣除，再计算普通股股东应享有的利润。\n\n基本公式：\n\n```text\n投资单位应确认的投资收益\n=（被投资单位净利润 - 应归属于优先股股东的股利）* 投资单位持股比例\n```\n\n关键在于：应归属于优先股股东的股利是否需要扣除。\n\n### 可累计优先股\n\n可累计优先股的股利即使本期没有宣告发放，也会累积到以后期间。\n\n因此，投资单位计算权益法投资收益时，应当扣除当期应归属于可累计优先股股东的股利。\n\n```text\n可累计优先股：\n无论是否宣告发放，都要扣除。\n```\n\n### 非累计优先股\n\n非累计优先股的股利如果本期没有宣告发放，通常不会累积到以后期间。\n\n因此，投资单位计算权益法投资收益时，只有在被投资单位宣告发放非累计优先股股利时，才扣除该部分股利。\n\n```text\n非累计优先股：\n宣告发放才扣除；\n没有宣告发放，不扣除。\n```\n\n### 对比表\n\n| 优先股类型 | 是否宣告发放股利 | 权益法确认投资收益时是否扣除 | 理由 |\n| --- | --- | --- | --- |\n| 可累计优先股 | 已宣告 | 扣除 | 股利归属于优先股股东 |\n| 可累计优先股 | 未宣告 | 扣除 | 股利权利会累积，普通股股东不能享有 |\n| 非累计优先股 | 已宣告 | 扣除 | 已宣告部分归属于优先股股东 |\n| 非累计优先股 | 未宣告 | 不扣除 | 未宣告部分不会累积 |\n\n### 例子\n\n甲公司持有乙公司普通股 30%，能够对乙公司施加重大影响，采用权益法核算。\n\n乙公司当年实现净利润 1,000 万元，优先股当年股利金额为 100 万元。\n\n#### 情形一：优先股为可累计优先股\n\n无论乙公司是否宣告发放优先股股利，甲公司计算投资收益时都要扣除 100 万元。\n\n```text\n甲公司应确认投资收益\n= (1,000 - 100) * 30%\n= 270（万元）\n```\n\n分录：\n\n```text\n借：长期股权投资--损益调整 270\n  贷：投资收益 270\n```\n\n#### 情形二：优先股为非累计优先股，且未宣告发放\n\n非累计优先股未宣告发放股利，不扣除 100 万元。\n\n```text\n甲公司应确认投资收益\n= 1,000 * 30%\n= 300（万元）\n```\n\n分录：\n\n```text\n借：长期股权投资--损益调整 300\n  贷：投资收益 300\n```\n\n#### 情形三：优先股为非累计优先股，且已宣告发放\n\n非累计优先股已经宣告发放股利，应扣除 100 万元。\n\n```text\n甲公司应确认投资收益\n= (1,000 - 100) * 30%\n= 270（万元）\n```\n\n分录：",
        "```text\n借：长期股权投资--损益调整 270\n  贷：投资收益 270\n```\n\n### 特殊情况：优先股分类为金融负债\n\n如果被投资单位发行的优先股被分类为金融负债，优先股股利通常已经作为利息费用等计入被投资单位损益。\n\n此时，被投资单位净利润本身已经扣除了相关费用。\n\n投资单位计算权益法投资收益时，通常不要重复扣除。\n\n### 易错点\n\n1. 不要把可累计优先股理解为“宣告才扣”，可累计优先股未宣告也要扣；\n2. 非累计优先股未宣告发放的，不扣除；\n3. 如果优先股被分类为金融负债，被投资单位净利润通常已经扣除了相关费用，投资单位不要重复扣除；\n4. 扣除优先股股利后，再乘以投资单位持有的普通股比例。\n\n### 记忆口诀\n\n```text\n权益法算普通股利润，先给优先股让路。\n\n可累计，不宣告也扣；\n非累计，宣告才扣；\n负债类，净利已扣，不再重复扣。\n```"
      ],
