        "topic": "非货币性资产交换",
        "difficulty": "高频基础",
        "question": "涉及补价时，怎么判断是否仍属于非货币性资产交换？",
        "summary": "非货币性资产交换可以涉及少量补价。通常补价占整个资产交换金额的比例低于 25%，仍按非货币性资产交换处理；达到或超过 25%，货币性成分过重。",
        "conclusion": [
            "有现金补价不必然排除非货币性资产交换。",
            "关键看补价占整个资产交换金额的比例。",
            "补价比例低于 25%，通常仍属于非货币性资产交换；达到或超过 25%，通常不再作为非货币性资产交换处理。"
        ],
        "reasoning": [
            "### 判断公式\n\n支付补价方通常这样判断：\n\n```text\n补价比例 = 支付的补价 /（换出资产公允价值 + 支付的补价）\n```\n\n收到补价方通常这样判断：\n\n```text\n补价比例 = 收到的补价 / 换出资产公允价值\n```\n\n如果比例低于 25%，说明交易主要还是非货币性资产之间的交换，补价只是辅助平衡价值差额。",
            "### 举例理解\n\n甲以公允价值 100 万元的设备换入乙的设备，同时收到乙支付的现金 20 万元。\n\n甲是收到补价方：\n\n```text\n补价比例 = 20 / 100 = 20%\n```\n\n乙是支付补价方，乙换出设备公允价值为 80 万元，另支付现金 20 万元：\n\n```text\n补价比例 = 20 /（80 + 20）= 20%\n```\n\n双方补价比例均低于 25%，通常仍属于非货币性资产交换。"
        ],
